(function(){const $=(s,el=document)=>el.querySelector(s);const S=[["start","Getting started"],["dash","Dashboard"],["audit","Project Audit"],["owners","How the $ add up"],["staff","Staffing Audit"],["track","Budget Tracker"],["ledgr","Actuals"],["fc","Forecast"],["acc","Accruals"],["flow","Where the numbers come from"],["config","Configuration"],["subs","Versions & submissions"],["data","Uploads & data"],["export","Exports"],["access","Access & privacy"],["tips","Tips"],["gloss","Glossary"]];const go=id=>`<a class="gopen" href="#/${id}">Open ›</a>`;function renderSidebar(activeId){const nav=$("#guide-nav");if(!nav)return;if(!nav.dataset.built){nav.innerHTML=`<div class="gs-head"><b>Contents</b></div>`+S.map(([id,t])=>`<a href="#/guide?s=${id}" data-s="${id}" class="glink">${t}</a>`).join("");nav.dataset.built="1";nav.querySelectorAll(".glink").forEach(a=>{a.onclick=e=>{e.preventDefault();const sid=a.dataset.s;history.replaceState(null,"",`#/guide?s=${sid}`);window.Guide.show(sid)}})}nav.querySelectorAll(".glink").forEach(a=>a.classList.toggle("on",a.dataset.s===activeId))}function setupScrollSync(){if(window.__guideSync)return;window.__guideSync=true;let t=null;window.addEventListener("scroll",()=>{if(document.body.dataset.route!=="guide")return;clearTimeout(t);t=setTimeout(()=>{const headings=S.map(([id])=>document.getElementById(`g-${id}`)).filter(Boolean);let cur=S[0][0];const scrollY=window.scrollY+120;for(const h of headings){if(h.offsetTop<=scrollY)cur=h.id.replace(/^g-/,"")}renderSidebar(cur)},50)},{passive:true})}function html(D){const tol=D?.tolerance??200,[hi,med]=D?.severity||[5e4,1e4],m=v=>"$"+Number(v).toLocaleString();return`\n<h1>How this site works</h1>\n<p>TrueUp checks the Atlas forecast against invoices, POs and budgets, shows FY actuals from Actuals next to the FY27 forecast, and is where budget managers build the monthly forecast, the quarter-end accruals, the Flash and the P&amp;L deck. New here? Take the site tour below, then the tour for each page you use. Click any topic on the left to jump to it.</p>\n\n<h2 id="g-start">Getting started</h2>\n<p class="gtourrow"><button type="button" class="sm" id="g-tour">Take the 30-second site tour</button> <button type="button" class="ghost sm" id="g-keys">Keyboard shortcuts</button></p>\n<ul>\n  <li><b>Pages</b> are the tabs across the top: Dashboard, Project Audit, Staffing Audit, Budget Tracker, Actuals, <b>Forecast ▾</b> and <b>Accruals ▾</b>. Forecast and Accruals don't open a page themselves: hover (or tap) them and pick Content or Marketing and the view you want. <b>Tools ▾</b> holds Export, Upload, the Guide, Configuration and <b>Data health</b>. You only see the pages you've been given access to.</li>\n  <li><b>Search (⌘K or /)</b> finds anything: an Atlas ID, PO, vendor, contractor, LOB, function, page or action. Pick a result and the right page opens with the filter set.</li>\n  <li><b>Action center</b> (Dashboard only, just under the tabs) lists what needs your attention on your LOBs and functions: open high-severity audit items, pending items, LOBs or functions forecasting over allocation, quarter-end and missing Actuals uploads. It's one line until you click it (click anywhere outside to close it); each item opens the page filtered to the lines behind it and scrolls you to them. <b>Configure</b> (inside Action center) turns each kind of item on or off for you; your choice is saved to your account. A <b>red border</b> means high-severity audit items (on your LOBs, shared lines or your functions); a <b>yellow border</b> means something to check. The other tiles are pending invoices, <b>Add Position IDs</b>, LOBs over budget, days to quarter close, Actuals uploads, and <b>Fix data mismatch</b> when a number doesn't tie across pages.</li>\n  <li><b>What a number leaves out.</b> Under each page's totals a short line says what's left out (e.g. <i>Excludes Toolbox, Vista (retired) · Cancelled/Hold projects</i>) with links to <b>Business rules</b> and <b>Sources</b>. Click a Dashboard card or an Budget Tracker step box to open <b>Where this comes from</b>: the source files and versions, the LOB values behind it and the rules applied. Configuration › Business rules lists every exclusion and the pages it applies to.</li>\n  <li><b>Filter chips.</b> Active filters, the search and Only mine show as chips under the filter row (Dashboard, Project Audit, Actuals); × removes one, Clear all removes them all.</li>\n  <li><b>Data health</b> (bottom of the Tools menu) opens right in the menu and shows how fresh each source is (Atlas, Actuals by org, forecast), how full each data store is, and whether the key numbers tie across pages. The dot beside it is green (OK), amber (stale or nearly full) or red (a source failed to load or a number doesn't tie). <b>Re-check</b> runs it again.</li>\n  <li><b>Refresh Atlas</b> (Tools menu, project admins): shows when Atlas data was last refreshed; click it to pull a fresh export now, in your own browser. It opens Atlas in a new tab: click the <b>TrueUp</b> bookmark there (the same one as TrueUp Fix; drag the newest from Project Audit › Queue if it asks you to start from the audit site). Atlas builds the export (about 2 minutes), the tab hands it back and closes, and TrueUp builds, checks and publishes it like Upload › Atlas export; the button then shows the new time. Atlas Freeze still applies to frozen forecasts and accruals. The Accruals PO / Crew rows and the Budget Tracker's week-over-week are rebuilt by the 10 AM run.</li>\n  <li><b>LOB icons</b>: every LOB name carries its app icon , so LOBs are easy to spot in tables, filters and cards. The header logo and the browser tab icon are the PD&amp;M logo.</li>\n  <li><b>Hover any summary card</b> (or ⓘ) to see what a number means and where it comes from.</li>\n  <li><b>Filters</b> (Org, Category, Budget Manager, LOB, Function, Function Manager, DRI, Check, FY, Quarter, Severity, Status) apply to Project Audit and Staffing Audit. The Budget Tracker uses the same bar without Done, Status, Severity, Check, Category and Search (they don't apply to allocation). Each one is multi-select with search. <b>Reset</b> (top right of the filter bar) clears everything in one click: every filter, the search, XLOB, Only mine and, on Staffing Audit, its switches and contractor search. On Project Audit and Staffing Audit, <b>Jump to …</b> and <b>Collapse all charts</b> sit in the same row. Hover the <b>ⓘ</b> next to <b>Status</b> for what Open and Pending mean. On <b>Staffing Audit</b>, the Search box filters the contractors list too: type an Atlas ID, a name, a vendor or a title and the list shows just those AIDs (exact AID and name matches first). <b>Only mine</b> (on by default for budget and function managers) shows just your LOBs and functions; turn it off, or press Reset, to see everything. Forecast and Accruals have the same switch as <b>Only my LOBs</b>. <b>Sync headers</b> keeps Only mine, XLOB and the org choice the same on every page; it's <b>on by default</b> (turn it off at the top of Configuration and each page keeps its own). <b>Sections</b>, picks which sections the page shows (Dashboard, Project Audit, Staffing Audit, Budget Tracker); your choice is saved to your account and comes back on any device. The Dashboard, Actuals and Forecast each have their own Reset at the end of their filter row: Actuals' clears its filters and search (Reset layout still resets the layout); Forecast's clears the search, $0 rows and Include XLOB, and collapses the rows.</li>\n  <li><b>XLOB</b> switch (in the filter bar, Content only; hover its ⓘ): off shows only Content LOB Dedicated functions and hides the shared XLOB functions (Resource Mgmt, Customer Journeys, Values, Studio Ops, Tech &amp; Spaces).</li>\n  <li><b>Click to drill in.</b> Almost every bar, card, segment and number opens the matching audit items with those filters applied. Filters live in the page address, so a copied link opens the same view.</li>\n  <li><b>Collapse anything:</b> click a section's header (the ⌄ arrow) to fold it; the page remembers. Each page's <b>Export</b> button (next to Reset) exports what that page shows.</li>\n  <li><b>On a phone:</b> the site works on small screens. Swipe the tab bar sideways; menus open from the bottom and wide tables scroll inside their card.</li>\n  <li><b>Data freshness:</b> hover the quarter badge (or open Tools › Data health) to see which Atlas export is loaded. When someone publishes a new one, open pages update on their own with a "Data updated" notice.</li>\n  <li><b>After a site update</b> press <kbd>⌘</kbd><kbd>⇧</kbd><kbd>R</kbd> once to make sure you have the newest version.</li>\n</ul>\n\n<h2 id="g-dash">Dashboard ${go("analytics")}</h2>\n<p>Last fiscal year's actuals against this year's outlook, by LOB. Budget managers only.</p>\n<ul>\n  <li><b>FY26 actuals</b> come from Actuals, by posted quarter, with the LOB merges and exclusions used everywhere else.</li>\n  <li><b>Current quarter</b> outlook = Atlas invoiced to date + the rest of the forecast. If invoices already exceed a row's forecast, the invoiced amount is used. FY27 Actuals isn't used until the quarter closes.</li>\n  <li><b>Later quarters</b> use the Forecast tab's figures (Atlas allocation + Judges). The dashed line on the chart is Atlas's allocation. Hover any colour in the chart legend for what it means.</li>\n  <li><b>Multi-select filters</b>: Org (Both/Content/Marketing), XLOB toggle, LOBs, Budget Managers, Function Managers, and Fiscal Years (FY26/FY27). Multiple items selectable in each filter.</li>\n  <li><b>On pace</b> shows how much of the current quarter's Atlas forecast is invoiced so far, against how invoices usually arrive. "Usual" comes from last FY's Actuals invoices, grouped by <b>spend quarter</b> (when the work happened) and placed by <b>posting date</b> (when the invoice hit), with accruals removed. It follows every filter at the top, including <b>Function</b> and <b>Budget item</b>. If a selection has too little history, it falls back to the whole org's pattern and says so.</li>\n  <li><b>Function</b> and <b>Budget item</b> filters apply to On pace only. The cards, quarter chart and LOB table use Forecast tab figures, which aren't split by budget item.</li>\n  <li><b>By LOB</b> table: click a row to drill into its functions (Content) or nat classes (Marketing). <b>Actuals ›</b> opens the Actuals tab filtered to that row's FY26 postings.</li>\n  <li><b>Biggest movers</b>: LOBs with the largest change between FY26 actuals and the FY27 outlook.</li>\n  <li><b>Sections</b> fold from their header; <b>Collapse all sections</b> folds them all. <b>Expand / collapse rows</b> in By LOB opens every LOB to its functions or nat classes.</li>\n</ul>\n\n<h2 id="g-audit">Project Audit ${go("items")}</h2>\n<p><b>Share</b> (Project Audit and Staffing Audit, for anyone who can see the page, next to Collapse all; a Staffing Audit link shares its audit items): turns whatever the filters show (leaving out items already ticked Done) into a link anyone at Nimbus can open for 14 days. It opens the same Project Audit view with only those items, which the viewer can filter further and click through to Atlas; nothing else on the site. The link copies to your clipboard; <b>Shared links</b> lists every link with who has opened it (people, opens and when; only you can see this) and Copy, Open and Revoke. The link keeps your filters, not a copy, so it always shows the latest published Atlas data and refreshes when Atlas does.</p>\n<p><b>Atlas Fix</b> (Project Audit and Staffing Audit, including the Contractors rows; not shared links): the blue wrench by an Atlas ID has <b>Add to queue</b>, <b>Remove from queue</b> and <b>Update in Atlas</b>. The wrench only appears on items it can fix. For Forecast, no invoice / Invoice &lt; or &gt; forecast it sets that quarter's forecast to what Atlas shows invoiced (in the record's own currency; LOB lines keep their split; other quarters aren't touched). For <b>Forecast &gt; PO/PR</b> it sets the quarter's forecast to the PO amount, for when the PO is right and the forecast is wrong. For Budget item over allocation and Billing complete - reallocate budget item it sets that function's quarter allocation to the forecast. Checks such as Allocation ≠ approved forecast have no wrench. <b>Queue (n)</b> next to Audit items lists what's queued (× removes one, Clear queue empties it) and <b>Fix in Atlas</b> opens Atlas with the list. Atlas only accepts changes made from its own pages, so the <b>TrueUp Fix</b> bookmark (drag it from the Queue menu to your Favorites bar once; re-drag it when the menu says a newer version is out) does the work there: click it on the Atlas tab, it re-reads each record live from Atlas, lists every change (old → new) and saves them after a 2-second countdown (Close stops it); the Atlas tab closes itself when it's done and you're back on the audit page. Changes are saved as you (Atlas shows you as the editor, with the justification "Match Forecast to Invoiced amount", "Match Forecast to PO amount" or "Match Allocation to Forecast amount"); each fixed item is ticked Done with a comment and leaves the queue.</p>\n<p><b>Currencies:</b> a project forecast in another currency (GBP, EUR, CAD…) is checked in that currency, against its invoices and PO/PR, and any gap is shown in USD. Exchange-rate differences between forecast and invoice don't create audit items.</p>\n<p><b>DRI</b> and <b>Comments</b> (Project Audit, Staffing Audit and shared links): DRI is the project's DRI from the Atlas export, with its own filter (Project Audit and Staffing Audit). Comments is a free-form comment per audit item that saves when you leave the field; everyone sees and can edit it (hover it for who last saved and when), and it stays on the item across daily refreshes. Both are in the exports.</p>\n<p><b>Done</b> (first column on Project Audit, Staffing Audit and shared links; ticked automatically when Atlas Fix saves the change): tick an audit item once it's handled. Anyone signed in can tick or untick; everyone sees the mark (hover it for who and when), and the <b>Done</b> filter splits Done from Not done. A mark stays on the item (Atlas ID, FY, quarter, check and function) through daily refreshes; if the issue is fixed in Atlas, the item simply drops off.</p>\n<p>Every project and budget check result from the latest Atlas export (staffing items are on <b>Staffing Audit</b>: Atlas Type <i>Individual Resource</i> or <i>Contingent Staffing</i>, every Content Managing Producer and Intl Managing Producer item, and staffing budget lines such as <i>P&amp;D Staffing (SHR)</i>, <i>Mktg Staffing (SHR)</i> or <i>LOB Dedicated Staffing</i>). One <b>audit item</b> = one Atlas ID (AID) × quarter × check, summed across that AID's LOB rows. Quarters where invoiced equals forecast (within ${m(tol)}) count as final and aren't checked. Gaps under ${m(tol)} are ignored.</p>\n<table><tr><th>Check</th><th>What it means</th><th>What to do</th></tr>\n  <tr><td>Forecast, no invoice</td><td>A closed quarter has forecast but $0 invoiced</td><td>Chase the invoice, or move/remove the forecast</td></tr>\n  <tr><td>Invoice &gt; forecast</td><td>Invoiced more than forecast</td><td>Raise the forecast to match</td></tr>\n  <tr><td>Invoice &lt; forecast</td><td>Partly invoiced</td><td>Lower the forecast, or confirm more invoices are coming</td></tr>\n  <tr><td>Forecast &gt; PO/PR</td><td>PO-billed AID whose forecast isn't covered by its PO + pending PR for the quarter or the FY (a pending PR that already has its PO# is counted once, in the PO; a PO shared by several Atlas IDs is split between them by their forecast that quarter)</td><td>Raise a PR/PO, or lower the forecast</td></tr>\n  <tr><td>PO phasing</td><td>The quarter is short but the FY is covered</td><td>Always Low severity. <b>Content:</b> accepted as compliant (status <i>Accepted</i>) because the FY PO/PR covers the FY forecast; phasing the PO by quarter to match Atlas is still preferred. <b>Marketing:</b> re-phase</td></tr>\n  <tr><td>Budget item over allocation</td><td>A budget item's forecast is over 100% of its allocation</td><td>Reallocate or trim</td></tr>\n  <tr><td>Billing complete - reallocate</td><td>Same, but every AID under it is fully billed, so the forecast is final</td><td>Move allocation into that line</td></tr>\n  <tr><td>Allocation ≠ approved forecast</td><td>Atlas's LOB allocation differs from the budget. <b>FY27 onward</b>: one full-year check per line against Atlas's Finance Budget (Content: the LOB's dedicated budget, i.e. its gross budget minus its XLOB share, against its non-XLOB allocation; Marketing: per LOB × natural class). FY26: per quarter against the approved forecast file</td><td>Update Atlas allocations (or the budget in Atlas)</td></tr>\n  <tr><td>Missing Position ID</td><td>A staffing AID has forecast (over $1) but no Position ID in Atlas. One item per AID and FY, $0 gap</td><td>Link the Position ID in Atlas, or review the role. On Staffing Audit, pick it in the Check filter to list the contractors</td></tr>\n</table>\n<ul>\n  <li><b>Severity and colour:</b> by default High ≥ ${m(hi)} gap, Medium ≥ ${m(med)}, otherwise Low (PO phasing is always Low). Each check's colour, its severity and whether it shows at all are set for everyone in <b>Configuration › Health checks › Atlas checks</b>.</li>\n  <li><b>Pending:</b> missing and under-invoiced items in the most recently closed quarter are Pending rather than Open, because invoices may still be in flight. Review them, but don't escalate yet.</li>\n  <li><b>Collapse sections:</b> click any section header. <b>Collapse all charts</b> and <b>Jump to audit items ↓</b> get you straight to the table. Your choices are remembered.</li>\n  <li><b>Audit items table:</b> sortable columns, pages of 200, AIDs link to Atlas. Export it with <b>Export › Data (CSV)</b>, or as a list of Atlas edits with <b>Change list (Excel)</b>.</li>\n  <li><b>Custom rules</b> (Configuration › Business rules) can hide items, change their severity or flag them with a note (⚑ under the Atlas ID).</li>\n  <li><b>Methodology &amp; exclusions</b> at the bottom lists the exact rules and the excluded (Canceled/Hold) AIDs.</li>\n</ul>\n\n<h2 id="g-owners">How the $ add up (Ownership and the charts)</h2>\n<div class="gcall"><b>The $ figure is the sum of the gaps on the open audit items, not the project's value.</b> Each item's gap is the size of its problem: forecast with no invoice = the forecast; invoice ≠ forecast = the difference; Forecast &gt; PO/PR = the uncovered amount; budget checks = the amount over allocation (or the difference from the approved forecast).</div>\n<ul>\n  <li><b>Counted per item, not per project.</b> An AID-quarter with two problems is two items, and both gaps are added. For example, an AID that's over-invoiced and also short on PO shows both. The numbers are therefore a <b>workload</b> measure ("how much needs fixing"), not a spend total. Don't add them to anything in Actuals or Atlas.</li>\n  <li><b>Overlap is limited.</b> In the current export, 605 LOB Dedicated AID-quarters have more than one transaction check (usually Forecast, no invoice + Forecast &gt; PO/PR). If you counted only the largest gap per AID-quarter, the transaction checks would total about $74M less.</li>\n  <li><b>Budget-level checks</b> (Budget item over allocation, Billing complete, Allocation ≠ approved forecast) are measured on the budget item or LOB, not on the AID, so they sit alongside the AID checks rather than duplicating one.</li>\n  <li><b>Several budget managers on one LOB:</b> Ownership shows the item under each of them, so adding every manager's total together counts those items more than once (about $14M today). The grand totals in the cards count each item once.</li>\n  <li><b>Ownership</b> only includes LOB Dedicated items. XLOB / shared items have no single LOB owner.</li>\n</ul>\n\n<h2 id="g-staff">Staffing Audit ${go("staffing")}</h2>\n<ul>\n  <li>The <b>Contractors</b> list: every Contingent Staffing / Individual Resource AID, one row per AID and FY, with rate, dates, status, forecast, invoiced and any audit items.</li>\n  <li><b>Audit items</b>: every staffing audit item (the same checks and columns as Project Audit, which no longer lists them). The summary cards and the quarter bars filter it in place; Action center's <i>Staffing · high severity</i> and <i>Staffing · pending</i> open it.</li>\n  <li><b>% of forecast invoiced by quarter:</b> the green part of each bar is the share of forecast invoiced. The yellow part is the <b>un-invoiced balance</b>: the sum of every AID's shortfall in that quarter. An AID billed above forecast doesn't offset another AID's shortfall. An orange line on top means the quarter is invoiced above 100%. Future quarters are hatched.</li>\n  <li><b>Click the balance</b> (the yellow "$ open" label) to list the AIDs not fully invoiced in that quarter, largest balance first. Clear it with the × on the contractors list's chip. Click elsewhere on a quarter to filter the audit items to it.</li>\n  <li><b>By vendor:</b> click a vendor to filter the contractors list. The list also has a search box and "Only with audit items".</li>\n  <li><b>Missing Position ID</b>: pick it in the <b>Check</b> filter (or click the <b>No Position ID</b> card) to list every contractor with forecast but no Position ID in Atlas. Each one carries a <i>Missing Position ID</i> tag. Every check you pick in the Check filter narrows the contractors list too. In ⌘K search, type <i>missing position</i>.</li>\n  <li>Sections collapse just like on Project Audit.</li>\n</ul>\n\n<h2 id="g-track">Budget Tracker ${go("tracking")}</h2>\n<ul>\n  <li>Follows the money in four steps, each with its own color: <b>① Budget</b> (FY27 onward: Atlas's Finance Budget, full year only, so a single-quarter view shows "–" for budget; grey) → <b>② Allocation</b> (loaded in Atlas, purple; should equal budget) → <b>③ Forecast</b> (Atlas forecast, blue; should build to allocation) → <b>④ Invoiced</b> (billed so far, green).</li>\n  <li>Two sections, each foldable from its header: <b>Org summary</b> and <b>By LOB</b>. Inside Org summary, click Content or Marketing to fold that org to a one-line total.</li>\n  <li><b>Summary cards</b> per org show the four steps for the full year, then one tile per quarter with allocation, forecast and invoiced, each checked against the step before (✓ = within $${(D?.tolerance??200).toLocaleString()}).</li>\n  <li><b>Period</b> (above the table): <b>Full year</b> shows the annual totals with a cell per quarter; Q1–Q4 shows that quarter on its own. Your choice is remembered.</li>\n  <li><b>Table</b>: columns are grouped under the same four headings plus <b>POs vs forecast</b> (POs opened against the forecast, and Forecast − POs). Quarter cells read <i>forecast / allocation</i>, then the gap and invoiced. Amounts are rounded; hover for the exact figure. Click an LOB to see its functions; → opens its audit items. Defaults to the budget FY and includes the Finance Adjustment line.</li>\n  <li><b>vs last week</b>: how allocation, forecast and POs have moved since the previous week's Monday export (only the ones that changed are shown; hover for last week's figures). The comparison moves forward every Monday.</li>\n  <li><b>Comment</b>: a free-form comment per org, LOB and function for the period shown, in the same style as the audit comments. It saves when you leave the field and everyone sees it within about 30 seconds (hover it for who last saved and when).</li>\n</ul>\n\n<h2 id="g-ledgr">Actuals ${go("ledgr")}</h2>\n<ul>\n  <li>A pivot table of the uploaded Actuals (Content and/or Marketing). Budget managers only.</li>\n  <li>Pick up to 3 row fields and 1 column field. Show amount or posting count. Add filters with <b>+ Filter</b> or search by Atlas ID, vendor, PO or text.</li>\n  <li><b>Click any number</b> to see the postings behind it. Export with Export › Data (CSV).</li>\n</ul>\n\n<h2 id="g-fc">Forecast ${go("forecast")}</h2>\n<p>The FY27 forecast in the same layout as the forecast workbooks. Forecast = Atlas allocation + Over/Under + Judge (Marketing also adds Growth Capex). <b>Over/Under</b> (hover its ⓘ) is the prior-quarter or prior-fiscal-year over/under accrual true-up. It stays blank for the open quarter; once a quarter closes it fills in from the latest FY27 Actuals (actuals posted in that quarter, including FY26 accrual reversals, minus the quarter's allocation).</p>\n<ul>\n  <li><b>Views:</b> Content (LOB › Function › Budget item) and Marketing (Nat Class › LOB › Initiative, or Nat Class › LOB › Function from the view menu). Rows nest: open a function to see its budget items (Content) or an initiative to see its functions (Marketing). A shared Content staffing budget item shows only that LOB's own allocation under each LOB. <b>Layouts:</b> Calculation (one quarter at a time, editable), Summary (FY vs annual budget, prior forecast, FoF) and Finance Commentary.</li>\n  <li><b>Judges:</b> enter them on the bottom rows (Content budget items; Marketing functions); they roll up to the rows above. Click a Judge (or Growth Capex) cell, type a number (<kbd>25000</kbd>, <kbd>-1.2m</kbd>, <kbd>(5,000)</kbd>) and press <kbd>Enter</kbd>. It saves straight away for everyone. <kbd>Tab</kbd> moves to the next cell; clear the cell to remove the Judge. Closed quarters are locked. A function (Marketing: initiative) with less than $100 allocated in the quarter is forecast at $0 automatically: the site enters a Judge of minus the allocation (grey italic) until you type one. That's why a Judge total can show a few dollars when every cell you see is blank; hover the Judge ⓘ for this.</li>\n  <li><b>Atlas forecast hover:</b> on Calculation, hover a function, budget item or initiative <b>name</b> to see that quarter's Atlas forecast against the allocation, POs opened against the forecast that needs one, and the gaps. Content staffing billed without a PO (anything but Invoice Type PO) isn't counted as needing a PO.</li>\n  <li><b>Comments 💬</b> on each row: the box opens empty, and every <b>Add comment</b> adds a new dated comment, newest first. The latest one goes to the Summary comments column in the export. Delete a comment with <b>Delete</b> under it (your own; admins can delete any).</li>\n  <li><b>Summary</b>: a LOB (or org total) whose forecast doesn't match its budget within $1,000 is highlighted in red.</li>\n  <li><b>Finance Commentary:</b> select the active quarter (Q1, Q2, Q3, Q4). By default it compares that quarter's forecast with the prior submission and prior-year actuals. The drop-downs over the quarter and full-year comparison columns pick any saved month and quarter instead (e.g. Q2 Nov), and the variances recalculate against it; a period with no data yet shows $0. The LRF column is the November LRF. Click a comment cell to write the variance explanation, then <kbd>Enter</kbd> saves. Grey text is carried over from the official submission; your edit replaces it. Clear the text to remove it. <b>Columns</b> (end of the header row, next to the comments) shows or hides any value, variance or comment column; a hidden column is hidden for every quarter and left out of the Excel export too. <b>Quarters</b> at the top of that menu hide a whole quarter (or the Full Year) at once: its values, variances and comments drop out of the export, and its columns hide while that quarter is shown.</li>\n  <li><b>Summary comments</b>: the Summary layout has a <b>Comments</b> column. Content: one comment per LOB and one per category under it (Art Buying, Design, Photo…); Marketing: one per LOB within each natural class. Type in the box; it saves when you click away, everyone sees it, and it's in History and the Excel export (Summary sheet, Comments column). The Marketing Summary also shows each LOB's FY27 budget within its natural class, and the variance.</li>\n  <li><b>FY27 vs Budget</b> (Calculation, every quarter): the full-year forecast (all four quarters, Judges included) against the full-year budget, updating as soon as a Judge changes. Content: on each LOB, against its LOB Dedicated budget (with the Intl switch on, against its INTL budget); Marketing: on each LOB's natural class. Red = more than $1,000 off.</li>\n  <li><b>Options</b> (toolbar, right): hover or click it for the page's view switches and actions, the same on Calculation, Summary and Finance Commentary. <b>View</b>: Only my LOBs, Include XLOB (Content Summary), $0 rows, Expand / collapse, Reset (back to your defaults). <b>Forecast</b>: History, Versions, Atlas Freeze and Export to Excel. <b>Intl</b> and <b>Change Log</b> stay on the toolbar. The <b>Totals</b> pills under the toolbar fold away from their heading (remembered in this browser).</li>\n  <li><b>Only my LOBs</b> is on when a page opens, for every budget and function manager. An admin can set a different default per person in Configuration › User access (<b>Only my LOBs</b> column). Switching it on a page is remembered in that browser.</li>\n  <li><b>Atlas Freeze</b> (Options › Forecast): stops this forecast (Content or Marketing, separately) picking up the daily Atlas refresh until an end date you choose. The forecast keeps the Atlas data from the moment it was frozen; Judges, comments and budgets keep working, and it goes back to live data on its own after the end date. Any LOB budget manager can turn it on, change the end date or unfreeze. Each takes three clicks (open Atlas Freeze · Freeze… / Unfreeze… · Yes) so it can't happen by accident. While it's on, the toolbar shows <i>Atlas Freeze · until &lt;date&gt;</i>. Only the Forecast is frozen: the audits, Budget Tracker and Accruals keep updating daily.</li>\n  <li><b>Change Log</b> (Forecast ▾ › Change Log; was <i>What changed</i>): how Atlas's FY27 allocations and forecast moved, for Content (by LOB › budget item) or Marketing (by nat class › LOB › initiative). <b>From</b> and <b>To</b> pick the two points compared: From defaults to the last official submission (else the last refresh), To defaults to today's / the latest stored Atlas export; either can be last Monday, the start of the quarter, or any stored export instead. <b>Filters</b> (multi-select, under the toolbar): LOB, Function, Budget item, Project, DRI, Quarter and Project change (New / Removed). Quarter picks which quarters are compared (none = the full FY27); Project, DRI and Project change look at every line, not only the highlighted ones, and open the lines they match. <b>Clear filters</b> resets them. The <b>Summary</b> pills below fold away from their heading. A line that moved by your highlight rule is highlighted and tagged (Allocation ↑/↓, Forecast ↑/↓, New / Removed line, Allocation moved between lines); <b>Only …</b> shows just those. <b>Highlight rule</b> sets the rule for you alone (saved to your account): a % and a $ amount, with <b>and</b> (both, the default: ≥ 10% and ≥ $25K) or <b>or</b> (either). Click a line for the projects behind it: new, removed (with status), moved from / to another line, forecast changes and quarter shifts, with who last edited them in Atlas and when. The history is stored on the site (one snapshot per refresh, about the last 14 days, 12 weeks of Mondays and each quarter's start), so it works for everyone without anyone's Mac.</li>\n  <li><b>Change Log on the Forecast</b>: turn on <b>Change Log</b> in the Forecast toolbar to mark the same changes on Calculation, Summary and Finance Commentary, using the same <b>From</b> / <b>To</b> and your highlight rule (Calculation and Finance Commentary compare the selected quarter, Summary the full year). A budget item or initiative that moved is highlighted with a <b>Δ</b> chip. Hover it for what moved (allocation or Atlas forecast before → now, shown only when it changed) and the projects behind it; click a project to open it in the Change Log, or the Δ to open the whole line. Rows above them, Summary rows and Finance Commentary rows show an <b>n changed</b> badge: hover it for the items, click one (or the badge) to open the Calculation with those items' LOBs and functions expanded, scrolled to the first one (outlined in blue).</li>\n  <li><b>History</b> lists every Judge change (from → to) and every comment (one dated line each), plus imports.</li>\n  <li><b>$0 rows</b> are hidden unless you turn on the <b>$0 rows</b> switch. <b>Intl</b> (Content, next to it) shows only the Intl functions and keeps the rows you have open. Totals never change when rows are hidden.</li>\n  <li><b>Comments and Judges survive new uploads.</b> They're matched to rows by name, so new Atlas or Actuals data never overwrites them. If Atlas renames a LOB or function, the old comment stays in History but won't appear on the renamed row.</li>\n</ul>\n\n<h2 id="g-acc">Accruals</h2>\n<p>Quarter-end work for Content and Marketing. Hover <b>Accruals ▾</b> in the tabs, pick the org, then the page. Budget managers only.</p>\n<ul>\n  <li><b>Fiscal year / Quarter</b> at the top of every Accruals page picks the quarter. The next quarter opens once the fiscal calendar reaches it and the current one is locked.</li>\n  <li><b>PO Accrual</b>: GRID (open POs and pending PRs) against the Atlas forecast. From FY27, Content has one line per PO × Atlas ID × quarter, using Atlas's quarter and Atlas's invoiced amount for each Atlas ID. Accrual = forecast − invoiced, never negative (where invoiced is above forecast the line accrues $0 and is flagged). Tabs: Accrual Calc, Pay Req, Late PRs (typed in), Line Items (the JV list), Atlas check and LOB pivots. Upload the GRID and Master PO List (Content) or PO ref table (Marketing) from Tools › Upload.</li>\n  <li><b>Crew Accrual</b>: contractors invoiced through Crew. Active roles accrue weekly rate × the weeks set for the quarter; ended roles accrue only their un-invoiced balance; managed-service vendors follow their vendor rule.</li>\n  <li><b>Flash</b>: Actuals posted + JVs to go (PO accrual + Crew + typed lines) against the forecast, grouped by LOB and budget category (Content) or nat class (Marketing). Click any number to see what's behind it; each number can carry its own comment. Delete a comment with <b>Delete</b> under it (your own; admins can delete any). The <b>Comments</b> column is a free-form field: type to add or change a row's comment, delete the text to remove it, and press Enter or click away to save (every change is in History). Comments on Prior Qtr adjustment and Additional entry can be deleted in their cell's editor. On <b>By budget manager</b>, <b>▸</b> on a LOB opens its functions (Marketing: LOB ▸ natural class ▸ function), each level with its own free-form comment (<b>Expand / collapse</b> opens them all); typed entries stay on the LOB row (Marketing: the natural-class row), and Marketing's forecast isn't by function. On the Marketing Flash the first four columns stay put while the rest scroll sideways. <b>Export</b> gives the Summary plus one tab per budget manager (Marketing: LOB › natural class), with each LOB's functions and their comments listed under it (grouped, so they can be collapsed; they're not added into the totals).</li>\n  <li><b>P&amp;L</b>: the quarter's P&amp;L deck. Actuals come from Actuals once the quarter has closed, otherwise from the Flash (choose with Actuals source). Edit titles, labels and commentary right on the slide, hide slides, present with ▶ and export to PowerPoint.</li>\n  <li><b>Finance Actuals</b>: the actuals sent to Finance for a quarter or the full year, against the M3 forecast, with comments per LOB and an Excel export. Content merges XLOB into the LOBs (Studio Ops stays its own line); Marketing spreads Bundle+ by the split in Business rules.</li>\n  <li><b>Editing</b>: every change needs a comment and is logged. <b>Lock quarter</b> freezes a page once it's final; exports of unlocked quarters are marked WORKING. PO Accrual and Crew Accrual each have their own lock; the <b>Flash</b> lock is the quarter-end close and also locks the <b>P&amp;L</b> and <b>Finance Actuals</b> (they have no lock of their own), and the next quarter opens on all three once it's locked. <b>Only my LOBs</b> narrows each page to yours.</li>\n  <li><b>Atlas Freeze (Accruals)</b>: on PO Accrual and Crew Accrual (separate from the Forecast's freeze). It keeps the org's Atlas PO / Pay Req and Crew rows as they were when frozen, until an end date, so the daily Atlas refresh (10 AM or Tools › Refresh Atlas) doesn't move a quarter-end accrual; the Flash and P&amp;L follow, since they read those pages. Any LOB budget manager can turn it on, change the date or unfreeze, three clicks each (Atlas Freeze · Freeze… / Unfreeze… · Yes). While it's on, the page shows <i>Atlas frozen · until &lt;date&gt;</i>. It ends on its own after the end date.</li>\n</ul>\n\n<h2 id="g-flow">Where the numbers come from</h2>\n<p>Four inputs feed every number on the site. Configuration adds the budgets, owners and business rules on top.</p>\n<table><tr><th>Input</th><th>How it gets here</th><th>Used by</th></tr>\n  <tr><td><b>Atlas export</b> (<i>export_all</i>)</td><td>Automatically every weekday at 10 AM Eastern (admins can also upload one)</td><td>Project and Staffing Audit, Budget Tracker, Forecast allocations, PO Accrual (expected expense), Pay Req, Crew Accrual</td></tr>\n  <tr><td><b>Actuals</b></td><td>Uploaded per org (Tools › Upload); a new file replaces the quarters it contains</td><td>Actuals page, Forecast Over/Under, Flash, P&amp;L, Finance Actuals</td></tr>\n  <tr><td><b>GRID</b> · Master PO List (Content) · PO ref table (Marketing)</td><td>Uploaded per org and quarter</td><td>PO Accrual</td></tr>\n  <tr><td><b>What you type</b></td><td>Saved as you go, logged in History</td><td>Judges, accrual edits, Late PRs, typed Flash lines, P&amp;L overrides and Adj., comments</td></tr>\n</table>\n<p><b>The chain at quarter end:</b> Atlas + GRID → <b>PO Accrual</b> · Atlas → <b>Crew Accrual</b> · Actuals + PO Accrual + Crew + typed lines → <b>Flash</b> (against the forecast) · Actuals, or the Flash until the quarter closes → <b>P&amp;L</b> · Actuals → <b>Finance Actuals</b>. Change an input and everything after it recalculates; locked quarters can't be edited.</p>\n\n<p><b>Forecast</b></p>\n<table><tr><th>Figure</th><th>Pulled from</th></tr>\n  <tr><td>Allocation</td><td>Atlas export: each project's allocation by quarter. Refreshes with every export.</td></tr>\n  <tr><td>Over/Under</td><td>Actuals: for a closed quarter, what posted in that quarter (including FY26 accrual reversals) minus the quarter's allocation. Blank for the open quarter.</td></tr>\n  <tr><td>Judge · Growth Capex</td><td>Typed by budget managers. Kept when new Atlas or Actuals data arrives.</td></tr>\n  <tr><td>Budget</td><td><b>FY27 onward:</b> Atlas's Finance Budget (full year, no quarters), read each weekday at 10 AM with the Atlas export. Content per LOB and region (US / INTL); each LOB's XLOB share is paid from its US budget, so its dedicated (discretionary) budget is gross − XLOB. Marketing per LOB × natural class. A LOB Atlas doesn't budget yet keeps its Configuration amount until it's added in Atlas. FY26: Configuration › LOB budgets.</td></tr>\n  <tr><td>Prior forecast, actuals, XLOB plugs</td><td>The uploaded forecast workbook, then the last official submission once one is locked.</td></tr>\n  <tr><td>LRF</td><td>The November LRF for each org, stored on its own (Finance Commentary).</td></tr>\n  <tr><td>Atlas forecast hover</td><td>The latest Atlas export: forecast, allocation and POs opened for the row and quarter.</td></tr>\n  <tr><td>What other pages compare with</td><td>The latest locked official submission; if none is locked, the latest saved forecast. FY26 accruals pages use the M3 forecast uploaded from the Flash workbook instead.</td></tr>\n</table>\n\n<p><b>PO Accrual</b>: GRID decides which POs; Atlas decides how much. From FY27, Content works by Atlas ID (below); Marketing and FY26 work by PO and GRID quarter.</p>\n<table><tr><th>Figure</th><th>Pulled from</th></tr>\n  <tr><td>Which lines</td><td>GRID: every open PO and pending PR (company code 56). A PO forecast in Atlas but not in GRID doesn't accrue. <b>Content FY27+:</b> one line per PO × Atlas ID × quarter, in the quarter Atlas has it (Atlas wins over GRID's quarter: GRID looks back, Atlas is current), so a PO on several Atlas IDs gets a line for each. <b>Marketing, FY26:</b> one line per PO × GRID quarter (Marketing: the spend quarter in the PR project number).</td></tr>\n  <tr><td>Expected expense</td><td>Atlas (Invoice Type PO). Content: the sum of Amount_LC by PO# and quarter. Marketing: the sum of Amount_US by spend quarter and PO (or PR), US only. You can override it per line.</td></tr>\n  <tr><td>Invoiced</td><td><b>Content FY27+:</b> Atlas's invoiced amount for that Atlas ID and quarter (how we report). GRID's invoiced total for the PO is the check: a $1,000+ difference is flagged. <b>Marketing, FY26:</b> GRID.</td></tr>\n  <tr><td>PO checks (Content FY27+)</td><td>GRID's PO amount and remaining value sit on the PO's first line. Flagged: accruals that add up to more than what's left on the PO (change order needed), Atlas invoiced ≠ GRID, and GRID quarters Atlas doesn't have.</td></tr>\n  <tr><td>Accrual</td><td>Expected − invoiced, never below $0 (lines below $0 are flagged).</td></tr>\n  <tr><td>Atlas ID, LOB, function</td><td><b>Content FY27+:</b> from Atlas for each Atlas ID (XLOB functions stay XLOB); a Master PO List fix still wins, and a GRID / Master PO List LOB that differs is flagged. <b>Marketing, FY26:</b> GRID's PR description and the Master PO List first, Atlas as the fallback.</td></tr>\n  <tr><td>LOB split (Marketing)</td><td>Atlas's Amount_US mix by LOB on the PO.</td></tr>\n  <tr><td>Pay Req</td><td>Atlas only (Invoice Type PayReq): the balance not yet invoiced. Content leaves out staffing; Marketing takes Marketing cost centers, US only, no FNB.</td></tr>\n  <tr><td>Late PRs</td><td>Typed in.</td></tr>\n  <tr><td>Line Items (the JV list)</td><td>Accrual Calc + Pay Req + Late PRs. This is what the Flash reads.</td></tr>\n</table>\n\n<p><b>Crew Accrual</b>: all from Atlas</p>\n<table><tr><th>Figure</th><th>Pulled from</th></tr>\n  <tr><td>Which contractors</td><td>Atlas rows with Invoice Type Crew for the org and quarter, by Atlas ID, kept by the status list in the quarter's Crew settings. Managed-service lines (SHR, FXD) are included.</td></tr>\n  <tr><td>Accrual</td><td>Active: Bill Rate × 40 (× 5 for daily rates) × the accrual weeks, capped at the uninvoiced balance. Inactive or no bill rate: the uninvoiced balance. Vendor rules (e.g. Talentry' invoice lag) override this.</td></tr>\n  <tr><td>Crew to go (for the Flash)</td><td>Active contractors' weekly rate × the flash weeks, plus managed-service accruals.</td></tr>\n  <tr><td>LOB split</td><td>Atlas's Percentage on each LOB row (falls back to the forecast mix).</td></tr>\n</table>\n\n<p><b>Flash</b>: Actuals posted this quarter + JVs still to go, against the forecast</p>\n<table><tr><th>Column</th><th>Pulled from</th></tr>\n  <tr><td>Prior Qtr Actuals · Current Qtr Actuals</td><td>Actuals postings in the quarter, split by spend quarter (earlier quarters vs this one).</td></tr>\n  <tr><td>PO Accrual (Marketing: Qx Accruals)</td><td>The PO Accrual page's Line Items for the quarter, by LOB (or by function for XLOB).</td></tr>\n  <tr><td>Crew to go</td><td>The Crew Accrual page: weekly rate × flash weeks, plus managed service.</td></tr>\n  <tr><td>Typed columns (yellow)</td><td>Typed on the Flash. Content: Prior Qtr adjustment, Additional entry. Marketing: re-accruals, missed Crew postings, xcharges, Growth Capex.</td></tr>\n  <tr><td>Forecast</td><td>FY26: the M3 forecast. FY27+: the latest official submission, or the latest saved forecast.</td></tr>\n  <tr><td>Delta · %</td><td>Flash − forecast.</td></tr>\n  <tr><td>Function rows (By budget manager)</td><td>The same Actuals, PO accrual and Crew lines by function. Typed lines stay on the LOB row. Marketing's forecast isn't by function.</td></tr>\n</table>\n<p>Content leaves out Vista and Brand Studio (Business rules › Flash exclusions).</p>\n\n<p><b>P&amp;L deck</b></p>\n<table><tr><th>Figure</th><th>Pulled from</th></tr>\n  <tr><td>Actuals</td><td><b>Auto</b> picks Actuals once the quarter has ended and Actuals has postings on or after its last day; until then, the Flash (Actuals posted + PO accrual + Crew + typed lines). <b>Actuals source</b> can force either.</td></tr>\n  <tr><td>Forecast</td><td>FY26: M3. FY27+: the same forecast the Flash uses.</td></tr>\n  <tr><td>By function / initiative</td><td>The same records, grouped (Content budget items sit under their functions, Marketing initiatives under theirs). Marketing functions come from Actuals, or from Atlas (each PO's or contractor's Atlas ID) while the deck runs on the Flash. The function and initiative slides also compare with the M3 forecast (December once it's complete).</td></tr>\n  <tr><td>FY by quarter</td><td>Actuals for earlier quarters, this quarter's actuals, and Configuration › LOB budgets.</td></tr>\n  <tr><td>Next forecast</td><td>The latest forecast on the site.</td></tr>\n  <tr><td>Overrides · Adj. · commentary</td><td>Typed on the deck (overridden figures are underlined).</td></tr>\n</table>\n\n<p><b>Finance Actuals</b>: Actuals only</p>\n<table><tr><th>Figure</th><th>Pulled from</th></tr>\n  <tr><td>Actuals</td><td>The latest Actuals upload for the quarter (or the full year). Content: by LOB and spend quarter. Marketing: natural class › LOB by quarter.</td></tr>\n  <tr><td>Forecast</td><td>M3 when uploaded for that year, otherwise the latest forecast for the year.</td></tr>\n  <tr><td>Content XLOB</td><td>Spread into the LOBs by the forecast's XLOB %. Studio Ops stays its own line.</td></tr>\n  <tr><td>Marketing Bundle+</td><td>Spread into its LOBs by the Bundle+ split in Business rules.</td></tr>\n  <tr><td>Comments</td><td>Typed per LOB.</td></tr>\n</table>\n\n<h2 id="g-config">Configuration</h2>\n<p><b>Tools › Configuration</b> holds the settings the whole site uses. You see the sections you've been given (marked <i>(view)</i> if you can look but not change). Changes show as <b>unsaved</b> at the bottom until you save them with a reason; everyone's open page then updates within about 15 seconds, and <b>History</b> keeps every saved version.</p>\n<ul>\n  <li><b>Sync headers</b> (top of the page): your own setting, <b>on by default</b>. <b>LOB budgets</b>: hover the small ↺ next to a LOB for its full change history. <b>LOB budget managers</b> and <b>Function managers</b> use a tick-box list (several people allowed, “support” marks a supporting manager); Function managers is laid out <b>LOB › function</b>, with each function's default owner listed underneath. <b>User access</b>: Configuration rights are set with a small – / V / E switch (none, view, edit); hover <b>BM data</b> for what budget-manager data covers. When on, Only mine, XLOB and the org choice stay the same as you move between pages.</li>\n  <li><b>LOB budgets</b>: <b>FY27 onward</b> this is a read-only view of Atlas's <b>Finance Budget</b> (full year; edit budgets in Atlas). Only admins can change anything in this section (the XLOB function budgets and shares, FY26); in User access it's – / V only for everyone else.</li>\n  <li><b>LOB budgets (detail)</b>: Content shows each LOB's US budget, its XLOB share (paid from US), US after XLOB, INTL, the LOB Dedicated (discretionary) budget and the gross total; Marketing opens each LOB into its natural classes. <b>Source</b> says Atlas, or <i>Configuration (not in Atlas yet)</i> for a LOB Atlas doesn't budget yet, which keeps its last Configuration amount until it's added in Atlas. FY26 budgets stay as before (by quarter, typed here: <code>2.5m</code>, <code>250k</code> or <code>250,000</code>). The <b>XLOB</b> section below still sets the shared functions' budgets and each LOB's share %. Budgets feed the Forecast Summary, the Budget Tracker and the audit's budget check.</li>\n  <li><b>LOB budget managers</b> and <b>Function managers</b>: who owns what. They drive the manager filters, <b>Only mine</b> and Action center. Allocation belongs to the LOB's budget manager: the allocation checks (Budget item over allocation, Billing complete - reallocate budget item, Allocation ≠ approved forecast), the Budget Tracker and LOBs over budget. Function managers own their functions' Atlas project checks. A function can follow each LOB's budget manager or have per-LOB overrides.</li>\n  <li><b>Accrual mapping</b>: finance project codes per LOB and LOB renames used on JV lines.</li>\n  <li><b>Business rules</b>: the rules every page uses, as pick-lists: XLOB functions, out-of-scope LOBs, LOB renames, Flash exclusions, the Bundle+ split and more. Add from the list (names come from the current Atlas and Actuals data) or type a new one; ✕ removes it. <b>Custom rules</b> let you write your own: <i>if</i> a field (LOB, function, budget item, vendor, check, gap…) matches, <i>then</i> leave the item out, set its severity or flag it. Each rule shows how many items it matches before you save.</li>\n  <li><b>Health checks</b>: <b>Atlas checks</b> sets each audit check's colour, its severity (by $ gap with your own thresholds, or always High / Medium / Low) and whether it shows, for everyone; the live count shows the effect before you save. Below that, what <b>Data health</b> and <b>Action center</b> look at and when they turn amber or red.</li>\n  <li><b>User access</b>: per person, which <b>pages</b> they see, which <b>Configuration</b> sections they can view or edit, and whether they have <b>budget manager data</b> (Judges, comments, the workbook baseline and Actuals). "Everyone else" covers people not listed.</li>\n  <li><b>History</b>: every save, with who, when, the reason and each change (old → new).</li>\n</ul>\n\n<h2 id="g-subs">Versions &amp; official submissions</h2>\n<ul>\n  <li><b>Versions</b> (Forecast tab): a full copy of the forecast (allocations, Judges, all comments, Finance Commentary, the workbook baseline and Actuals). One is saved automatically before every Atlas, Actuals or workbook upload. Save one yourself any time with a label. The newest ~70 are kept.</li>\n  <li><b>View</b> opens a version read-only in the Forecast tab, with a banner and <b>Back to current</b>. The Dashboard keeps showing the current forecast. <b>Marketing / Content Excel</b> downloads it in the workbook layout.</li>\n  <li><b>Lock as official submission</b> (admins, in Versions):\n    <ul>\n      <li>You can lock the current forecast, OR select <b>any saved version</b> from the bottom table and click <b>Lock as official</b>. The lock is only allowed when the forecast matches budget within $1,000, per LOB and in total; otherwise it lists the LOBs that are off and by how much. The submission keeps the Atlas allocations as they were when it was locked, so later comparisons tie to it.</li>\n      <li>Once locked, the forecast becomes <b>the official submission</b>: the following quarter's submission (e.g. Q2 after Q1 is locked) updates its prior-forecast comparison columns and carried-over Finance Commentary comments to compare against it!</li>\n      <li><b>Unpublish / Unlock</b>: If additional edits or changes need to happen, click <b>Unpublish / Unlock</b> (on the Forecast tab subtitle or in the Versions dialog). This unlocks the forecast and reverts the comparison basis so budget managers can continue editing.</li>\n    </ul>\n  </li>\n  <li><b>Box backup:</b> every version and submission is automatically written to <i>Project Audit/Forecast Versions/</i> in Box (Excel workbook with Calculation, Finance Commentary, and Comments log, plus compressed JSON data) each time the build runs.</li>\n</ul>\n\n<h2 id="g-data">Uploads &amp; where the data comes from</h2>\n<p>Everything below is under <b>Tools › Upload</b>, grouped by Audit, Content and Marketing. The org of a Actuals or workbook file is detected from the file.</p>\n<table><tr><th>Upload</th><th>Who</th><th>What it updates</th></tr>\n  <tr><td>Atlas export</td><td>Admins</td><td>One <i>export_all</i> CSV refreshes the audit, staffing, allocation tracking and the forecast allocations for everyone. It's processed in your browser; you see a summary before publishing.</td></tr>\n  <tr><td>Actuals</td><td>Budget managers</td><td>Content or Marketing Actuals CSV. It's combined with what's stored: quarters in the new file replace those quarters, others are kept. FY26 is closed: each org has one final FY26 file. FY27 has its own file, uploaded as it's updated. Save the same file in the shared Ledger folder (one per org) so Data health's site-vs-folder check matches.</td></tr>\n  <tr><td>Forecast workbook</td><td>Budget managers</td><td>The submitted Marketing/Content workbook: prior forecast, actuals, comments and XLOB plugs. The November LRF is loaded separately by an admin.</td></tr>\n  <tr><td>GRID · Master PO List · PO ref table</td><td>Budget managers</td><td>Inputs for the PO Accrual of the quarter shown on the Accruals page.</td></tr>\n</table>\n<p>A new Atlas export is also published automatically each weekday at 10 AM Eastern. Actuals is stored one quarter at a time for the open year, so a full year fits. The Apps LOB is retired and removed everywhere. Navigator is excluded from the Content forecast, and Summit LOBs from the Marketing forecast.</p>\n\n<h2 id="g-export">Exports</h2>\n<p>Each page's <b>Export</b> button exports what you're looking at. <b>Tools › Export</b> has the full list:</p>\n<ul>\n  <li><b>Data (CSV):</b> everything on the current tab with all fields.</li>\n  <li><b>Change list (Excel):</b> the Atlas edits to make for the filtered items, with a Done column. Excludes Pending items.</li>\n  <li><b>Marketing / Content forecast (Excel):</b> Summary, Finance Commentary (every quarter and the full year on one sheet, only the columns shown on the page) and the Calculation sheet with the nested rows, plus <b>Atlas Source</b> as the last sheet: the org's FY27 Atlas allocations, in the raw Atlas export's own column layout. On Calculation, each row's Allocation is a SUMIFS on Atlas Source, subtotals add up their rows, and Forecast = Allocation + Over/Under (+ Growth Capex) + Judge; Over/Under, Growth Capex and Judge are values. To refresh the file, paste a new Atlas export into Atlas Source (all columns, from cell A1). Amounts update for every row already in the file; a budget item, function or LOB that's new in Atlas needs a fresh export from the site. A saved version or an Atlas Freeze exports the forecast's own allocations instead, so the file always matches what the site shows.</li>\n  <li><b>Accruals (per org):</b> PO Accrual, Crew Accrual and Flash (Excel), the P&amp;L deck (PowerPoint) and Finance Actuals (Excel).</li>\n</ul>\n\n<h2 id="g-access">Access &amp; privacy</h2>\n<ul>\n  <li>The site is only for the people in <b>Configuration › User access</b> (the sections ticked for them), the budget and function managers set up in Configuration (the <b>Other managers</b> sections, e.g. Dashboard, audits and Budget Tracker) and admins. Anyone else who signs in sees no sections; a shared link still opens just that link's items.</li>\n  <li>The Dashboard, Actuals, Forecast, Accruals, Judges, comments, Finance Commentary, versions and submissions are private to the budget managers. Admins manage who sees what in <b>Configuration › User access</b> (pages, Configuration sections and budget manager data).</li>\n  <li>Raw Atlas exports, Actuals files and workbooks are never published as files; only the processed results are stored.</li>\n</ul>\n\n<h2 id="g-tips">Tips</h2>\n<ul>\n  <li>Hovering any table highlights its row and column.</li>\n  <li>Start your review from <b>Ownership</b> → your name → a LOB → <b>→</b>, to see only your items.</li>\n  <li>Use the Budget Manager filter on Staffing Audit to see only your contractors, then click a yellow balance to find what hasn't been billed.</li>\n  <li>Before a big change, save a version with a label. It costs nothing and you can always look back.</li>\n  <li>Start your day on the Dashboard: open <b>Action center</b> and click the top item; it takes you to exactly the lines to fix.</li>\n  <li>Press <kbd>?</kbd> for keyboard shortcuts, or <kbd>G</kbd> then a letter to jump between pages.</li>\n</ul>\n\n<h2 id="g-gloss">Glossary</h2>\n<p>Every ⓘ and hover box on the site, in one place, by page.</p>\n<table class="ggloss"><tr><th>Where</th><th>Term</th><th>What it means</th></tr>\n  <tr><td rowspan="2">All pages</td><td>What's left out</td><td>The line under a page's totals listing what the numbers exclude (retired LOBs, Cancelled/Hold projects…), with links to Business rules and Sources.</td></tr>\n  <tr><td>Where this comes from</td><td>Opens from a Dashboard card or a tracker step box: the source files and versions, the LOB values behind the number and the rules applied.</td></tr>\n  <tr><td rowspan="6">Dashboard</td><td>Chart</td><td>Last year's actuals vs this year's outlook, by LOB.</td></tr>\n  <tr><td>On pace</td><td>How much of this quarter's forecast is invoiced so far, against how invoices for a quarter's spend usually arrive. Follows the filters above.</td></tr>\n  <tr><td>Spread</td><td>The range of last year's quarters, slowest to fastest: how much of a quarter's spend was invoiced by each point in the quarter.</td></tr>\n  <tr><td>Average</td><td>Last year's average share of a quarter's spend invoiced by each point in the quarter.</td></tr>\n  <tr><td>Invoiced</td><td>How much of this quarter's Atlas forecast is invoiced so far.</td></tr>\n  <tr><td>Export date</td><td>The date of the Atlas export the numbers come from.</td></tr>\n  <tr><td rowspan="3">Project / Staffing Audit</td><td>Status: Open</td><td>Needs action: a real gap in a closed quarter, or a PO / budget issue in any quarter.</td></tr>\n  <tr><td>Status: Pending</td><td>Missing or under-invoiced in the most recently closed quarter. Invoices may still be landing: review, but don't escalate yet. Current and future quarters are only checked for PO coverage and budget.</td></tr>\n  <tr><td>XLOB</td><td>Off shows only Content LOB Dedicated functions and hides the shared XLOB functions (Resource Mgmt, Customer Journeys, Values, Studio Ops, Tech &amp; Spaces).</td></tr>\n  <tr><td rowspan="3">Staffing Audit</td><td>Contractors</td><td>One row per staffing AID and FY. The Org, Budget Manager, LOB, Function, Function Manager and FY filters apply.</td></tr>\n  <tr><td>Last invoiced week</td><td>The latest weekly invoice in the quarter: <i>final ✓</i> once it reaches the quarter's last week, <i>through m/d</i> before that, <i>none yet</i> when nothing is billed.</td></tr>\n  <tr><td>Missing Position ID</td><td>Forecast but no Position ID in Atlas.</td></tr>\n  <tr><td rowspan="4">Budget Tracker</td><td>Quarter cell</td><td>Hover for the exact allocation, forecast and invoiced.</td></tr>\n  <tr><td>POs opened · Forecast − POs</td><td>The POs opened against the period's forecast, and how much forecast they don't yet cover.</td></tr>\n  <tr><td>vs last week</td><td>The change in forecast, allocation and POs since the previous week's Monday export; hover for last week's figures.</td></tr>\n  <tr><td>Comment</td><td>Hover for who last saved it and when.</td></tr>\n  <tr><td rowspan="9">Forecast</td><td>Over/Under</td><td>The prior-quarter or prior-FY over/under accrual true-up: for a closed quarter, the Actuals posted in it (including FY26 accrual reversals) minus the quarter's allocation. Blank (–) for the open quarter.</td></tr>\n  <tr><td>Judge</td><td>Your adjustment to Atlas's allocation: Forecast = Allocation + Over/Under (+ Growth Capex for Marketing) + Judge. Entered on the bottom rows; rolls up to the totals.</td></tr>\n  <tr><td>Automatic $0 (grey italic)</td><td>A function (Marketing: initiative) with less than $100 allocated in the quarter is forecast at $0: the site enters a Judge of minus the allocation. Those rows hide as $0 rows, but their few dollars still count in the totals. Typing a Judge replaces it.</td></tr>\n  <tr><td>Atlas forecast hover</td><td>On a row name: Atlas forecast, allocation and the gap; POs opened and Forecast − POs. Content staffing billed without a PO shows separately and is left out of the PO gap (Needing a PO − POs).</td></tr>\n  <tr><td>Red on Summary</td><td>The forecast doesn't match budget within $1,000. Submissions can't be locked until it does.</td></tr>\n  <tr><td>Summary Comments</td><td>A comment per Content LOB and category, or per Marketing LOB within a natural class; hover for who saved it and when. Exported on the Summary sheet.</td></tr>\n  <tr><td>FY27 vs Budget</td><td>Calculation: the full-year forecast (Judges included) minus the full-year budget, live as Judges change. Content LOB rows (LOB Dedicated budget; INTL with the Intl switch on), Marketing natural-class rows. Hover for both figures.</td></tr>\n  <tr><td>Change Log tags</td><td>Allocation ↑/↓, Forecast ↑/↓ (by your highlight rule; default ≥ 10% and ≥ $25K), New / Removed line, Allocation moved (a drop on one line matched by the same rise on another in the LOB). Projects: New, Removed (status), Moved from / to, Forecast ↑/↓, Quarter shift (same FY total, different quarters).</td></tr>\n  <tr><td>Atlas Freeze · until &lt;date&gt;</td><td>This forecast is frozen: it keeps the Atlas data from when it was frozen and ignores the daily refresh until after that date. Click it to see who froze it, change the date or unfreeze (LOB budget managers, three clicks).</td></tr>\n  <tr><td rowspan="13">Accruals</td><td>PO Accrual · Accrual Calc</td><td>Content FY27+: one row per PO, Atlas ID and quarter. GRID gives the POs and what's left on them; Atlas gives the forecast, invoiced and the quarter.</td></tr>\n  <tr><td>Pay Req</td><td>Atlas projects with Invoice Type PayReq with a balance not yet invoiced (Content leaves out staffing; Marketing: non-Intl cost centers, US, no FNB). Untick to leave a line out; click the amount to change it (comment required).</td></tr>\n  <tr><td>Late PRs</td><td>PRs not yet in GRID. Each becomes a JV line; typing the Atlas ID fills in LOB, function, cost center, GL, vendor and project code.</td></tr>\n  <tr><td>Line Items</td><td>The JV list: every Accrual Calc, Pay Req and late PR line with division, cost center, GL, line item text and project code.</td></tr>\n  <tr><td>Atlas check</td><td>Accrual Calc by PO and quarter next to Atlas's forecast − invoiced. A delta of $1,000 or more is flagged.</td></tr>\n  <tr><td>LOB Pivots</td><td>What the Flash reads: accrual by LOB, by XLOB function, and this-quarter-only by LOB, tied to the Line Items total.</td></tr>\n  <tr><td>Master PO List</td><td>Navigator POs to LOB, budget item, function and quarter; used when one PO covers several Atlas IDs. The tab lists only lines that need a decision.</td></tr>\n  <tr><td>Crew Accrual</td><td>One line per Crew contractor. Weekly = bill rate × 40 (hourly) or × 5 (daily). Active: weekly × the weeks set; inactive: only the uninvoiced balance.</td></tr>\n  <tr><td>Weeks &amp; vendors</td><td>How many weeks to accrue for regular Crew contractors, and a different number or method for individual vendors such as Teamstaff Partners.</td></tr>\n  <tr><td>Flash</td><td>Actuals posted this quarter + JVs still to go, against the quarter's forecast. <i>By budget manager</i> groups the same Flash by each LOB's budget manager.</td></tr>\n  <tr><td>P&amp;L · Finance Actuals</td><td>P&amp;L: the quarter's deck (Actuals once closed, the Flash until then). Finance Actuals: the Actuals by LOB sent to Finance, against M3, with a comment per LOB.</td></tr>\n  <tr><td>Sources</td><td>The files behind the page: Actuals, GRID, Master PO List / PO ref table, Atlas and the forecast it compares with.</td></tr>\n  <tr><td>Atlas frozen · until &lt;date&gt;</td><td>This org's PO / Pay Req and Crew rows are frozen at the Atlas data from when it was frozen; daily refreshes don't change them until after that date. Atlas Freeze (on PO / Crew Accrual) shows who froze it and lets a LOB budget manager change the date or unfreeze.</td></tr>\n  <tr><td rowspan="6">Configuration</td><td>↺ (LOB budgets)</td><td>The LOB's full budget change history (FY26).</td></tr>\n  <tr><td>Finance Budget (FY27+)</td><td>Each LOB's full-year budget from Atlas's Finance Budget, read each weekday at 10 AM. Read only on the site; edit it in Atlas.</td></tr>\n  <tr><td>Configuration (not in Atlas yet)</td><td>Atlas has no budget for this LOB yet, so its last Configuration amount is used until it's added in Atlas.</td></tr>\n  <tr><td>XLOB share</td><td>A Content LOB's share of the XLOB functions' budget (fixed %). It's paid from the LOB's US budget, so the LOB's dedicated (discretionary) budget = gross budget − XLOB share (e.g. TV App: $13.9M gross − $3.5M XLOB ≈ $10.4M).</td></tr>\n  <tr><td>BM data</td><td>Budget manager data: Forecast Judges and comments, the workbook baseline (prior quarter, LRF, commentary), Actuals uploads and Accruals work. Ticking it gives read + write to all of it; unticking removes it at once.</td></tr>\n  <tr><td>– / V / E</td><td>Configuration rights per section: none, view or edit.</td></tr>\n  <tr><td rowspan="1">Actuals</td><td>Actuals ⓘ</td><td>The Actuals file loaded, and the number of postings and total in view. When a column field has too many values, the largest are shown and the rest go into Other.</td></tr>\n</table>`}const TOUR_AT={"g-dash":"analytics","g-audit":"items","g-staff":"staffing","g-track":"tracking","g-ledgr":"ledgr","g-fc":"forecast","g-acc":"accruals","g-config":"config"};const canTour=k=>k==="config"?window.SiteConfig?.canConfig?.():window.SiteConfig?.can?.(k)??true;const placeTours=()=>{if(!window.Learn)return;for(const[id,k]of Object.entries(TOUR_AT)){const h=document.getElementById(id);if(!h||h.nextElementSibling?.classList.contains("gtourrow"))continue;if(!canTour(k))continue;const T=window.Learn.PAGE_TOURS[k];if(!T)continue;h.insertAdjacentHTML("afterend",`<p class="gtourrow"><button type="button" class="sm" data-ptour="${k}">Tour ${T[0]} · ${T[2].length} steps</button></p>`)}};document.addEventListener("click",e=>{const b=e.target.closest("[data-ptour]");if(b){e.preventDefault();window.Learn?.pageTour(b.dataset.ptour)}});new MutationObserver(()=>{if(document.getElementById("g-dash")&&Object.keys(TOUR_AT).some(id=>document.getElementById(id)&&!document.querySelector(`#${id} + .gtourrow`)&&canTour(TOUR_AT[id])))placeTours()}).observe(document.body,{childList:true,subtree:true});window.addEventListener("hashchange",()=>setTimeout(placeTours,300));document.addEventListener("click",e=>{if(e.target.closest("#g-tour")){e.preventDefault();location.hash="#/analytics";setTimeout(()=>window.Learn?.tour(0),900)}else if(e.target.closest("#g-keys")){e.preventDefault();window.Learn?.keys()}});window.Guide={show(sec){const root=$("#guide-root");if(!root.dataset.done){root.innerHTML=html(window.AuditData?.());root.dataset.done="1";setupScrollSync()}renderSidebar(sec||S[0][0]);const el=sec&&$(`#g-${sec}`,root);setTimeout(()=>el?el.scrollIntoView({behavior:"smooth",block:"start"}):window.scrollTo({top:0}),60)}}})();